# PSC #395 Intake Agents Lambda, packaged as one file.
# The modules it uses are embedded below; the code of the file's own entry module follows the marker near the end.
# Entry module: payment_query_platform.intake.invoke_agents
# Handler: lambda_function.lambda_handler
# Needs boto3 and psycopg in the Lambda deployment package.
import importlib.abc as _psc_abc
import importlib.util as _psc_util
import sys as _psc_sys
